ae_int_t ae_tickcount()
{
#if defined(X_FOR_WINDOWS)
    return (int)GetTickCount();
#elif defined(X_FOR_LINUX)
    struct timeval now;
    int64_t r, v;
    gettimeofday(&now, NULL);
    v = (int64_t)now.tv_sec;
    r = v*1000;
    v = (int64_t)(now.tv_usec/(suseconds_t)1000);
    r = r+v;
    return (ae_int_t)r;
#else
    return (ae_int_t)0;
#endif
}

