{
#if defined(X_FOR_WINDOWS)
    (*p_proc) = GetProcAddress(lib, name);
#elif defined(X_FOR_LINUX)
    (*p_proc) = dlsym(lib, name);
#else
#error X-environment is not defined
#endif
    if( (*p_proc)==NULL )
    {
        fprintf(stderr, "ALGLIB: unable to load '%s'\n", name);
        abort();
    }
}

