static void x_vector_init_empty(x_vector *x, int datatype)
{
    x->cnt = 0;
    x->datatype = datatype;
    x->on_free = ACT_DROP;
    x->last_action = ACT_UNCHANGED;
    x->x_ptr.p_ptr = NULL;
}
           
static void x_matrix_init_empty(x_matrix *x, int datatype)
{
    x->rows = 0;
    x->cols = 0;
    x->stride = 0;
    x->datatype = datatype;
    x->on_free = ACT_DROP;
    x->last_action = ACT_UNCHANGED;
    x->x_ptr.p_ptr = NULL;
}

/**************************************************************************************************
Creates X-vector structure from Java array.

INPUT PARAMETERS:
    env             -   JNI env
    x               -   x-vector structure, depending on x_operation can be considered initialized
                        or uninitialized
    jarray          -   pointer to Java 1D array or corresponding relocatable wrapper object.
                        Can be NULL, in this case x is initialized as empty vector (x_operation MUST be X_CREATE).
    is_rlc_wrapper  -   if true, jarray points to an instance of relocatable wrapper (a class that
                        allows to return reallocated arrays, emulating passing parameters by
                        reference)
    datatype        -   DT_BOOL, DT_INT, DT_REAL or DT_COMPLEX
    x_operation     -   one of the following:
                        * X_CREATE - x points to uninitialized instance, new array is created
                        * X_SET    - x points to initialized array (which may have different datatype),
                                     previois contents is freed prior to allocating new storage
                        * X_REWRITE- x points to initialized array of the same size and type, 
                                     array contents is rewritten without reallocation
    e_flag          -   points to exception flag
    e_msg           -   points to exception message
    
OUTPUT PARAMETERS:
    x               -   new X-array (on exception it is still valid, although only partially
                        initialized, and you should properly clear it in order to avoid memory
                        leaks)
    e_flag          -   on exception it is set to X_INPUT_FAILURE, on success is not modified
    e_msg           -   on exception it is set to error message, on success is not modified
    
EXCEPTIONS AND ERROR HANDLING:
    this function sets e_flag only in the following cases:
    * input is a complex array that has null elements
    
    All other errors are considered critical integrity failures, with error message being printed
    and program being terminated immediately.
**************************************************************************************************/
static void x_vector_from_array(JNIEnv *env, x_vector *x, jobject jarray, int is_rlc_wrapper, int datatype, int x_operation, int32_t *e_flag, const char **e_msg)
{
    /* determine type signatures */
    const char *arr_sig = NULL;
    int elem_size = 0;
    if( datatype==DT_BOOL )
    {
        arr_sig = "[Z";
        elem_size = sizeof(ae_bool);
    }
    if( datatype==DT_INT )
    {
        arr_sig = "[I";
        elem_size = sizeof(ae_int_t);
    }
    if( datatype==DT_REAL )
    {
        arr_sig = "[D";
        elem_size = sizeof(double);
    }
    if( datatype==DT_COMPLEX )
    {
        arr_sig = "[Lalglib/alglib$complex;";
        elem_size = sizeof(ae_complex);
    }
    CRITICAL_ASSERT((arr_sig!=NULL) && (elem_size>0), "ALGLIB: integrity check 7146 at x_vector_from_array() failed");
    
    /* if array is passed via relocatable wrapper, extract it from the wrapper object */
    if( is_rlc_wrapper )
    {
        jclass  rlc_class = (*env)->GetObjectClass(env, jarray);
        CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 6542 at x_vector_from_array() failed");
        //
        jfieldID fid_val = (*env)->GetFieldID(env, rlc_class, "val", arr_sig);
        CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 7721 at x_vector_from_array() failed");
        //
        jarray = (*env)->GetObjectField(env, jarray, fid_val);
    }
    
    /* handle NULL input */
    if( jarray==NULL )
    {
        CRITICAL_ASSERT(x_operation==X_CREATE, "ALGLIB: integrity check 6855 failed");
        x_vector_init_empty(x, datatype);
        return;
    }
    
    /* read Java array length */
    jsize _length = (*env)->GetArrayLength(env, jarray);
    
    /* initialize x-array depending on x_operation being passed */
    if( x_operation==X_CREATE )
    {
        x->cnt = _length;
        x->datatype = datatype; // TODO: attach to already allocated memory!!!!!!!!!!!!!
        x->on_free = ACT_XFREE;
        x->last_action = ACT_UNCHANGED;
        if( x_malloc(&x->x_ptr.p_ptr, _length*elem_size)!=X_OK )
            CRITICAL_ASSERT(0, "ALGLIB: x_malloc at x_vector_from_array() failed");
    }
    if( x_operation==X_SET )
    {
        if( x->on_free==ACT_XFREE )
            x_free(x->x_ptr.p_ptr);
        x->datatype = datatype;
        x->cnt = _length;
        x->on_free = ACT_XFREE;
        if( x_malloc(&x->x_ptr.p_ptr, _length*elem_size)!=X_OK )
            CRITICAL_ASSERT(0, "ALGLIB: x_malloc at x_vector_from_array() failed");
        x->last_action = ACT_NEW_LOCATION;
    }
    if( x_operation==X_REWRITE )
    {
        CRITICAL_ASSERT(x->datatype==datatype,  "ALGLIB: trying to X_REWRITE x-vector - types don't match");
        CRITICAL_ASSERT(x->cnt==_length,        "ALGLIB: trying to X_REWRITE x-vector - sizes don't match");
        CRITICAL_ASSERT(x->last_action==ACT_UNCHANGED ||
                        x->last_action==ACT_SAME_LOCATION ||
                        x->last_action==ACT_NEW_LOCATION, "ALGLIB: integrity check 6145 failed at x_vector_from_array()");
        if( x->last_action==ACT_UNCHANGED )
            x->last_action = ACT_SAME_LOCATION;
    }
   
    /* read array items */
    if( datatype==DT_BOOL )
    {
        jboolean *in_array = (*env)->GetBooleanArrayElements(env, jarray, NULL);
        CRITICAL_ASSERT(in_array!=NULL, "ALGLIB: integrity check 9455 at x_vector_from_array() failed");
        ae_bool *p = (ae_bool*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<_length; i++)
            p[i] = in_array[i] ? ae_true : ae_false;
        (*env)->ReleaseBooleanArrayElements(env, jarray, in_array, 0);
    }
    else if( datatype==DT_INT )
    {
        jint *in_array = (*env)->GetIntArrayElements(env, jarray, NULL);
        CRITICAL_ASSERT(in_array!=NULL, "ALGLIB: integrity check 9654 at x_vector_from_array() failed");
        ae_int_t *p = (ae_int_t*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<_length; i++)
            p[i] = in_array[i];
        (*env)->ReleaseIntArrayElements(env, jarray, in_array, 0);
    }
    else if( datatype==DT_REAL )
    {
        jdouble *in_array = (*env)->GetDoubleArrayElements(env, jarray, NULL);
        CRITICAL_ASSERT(in_array!=NULL, "ALGLIB: integrity check 1656 at x_vector_from_array() failed");
        double *p = (double*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<_length; i++)
            p[i] = in_array[i];
        (*env)->ReleaseDoubleArrayElements(env, jarray, in_array, 0);
    }
    else if( datatype==DT_COMPLEX )
    {
        ae_complex *p = (ae_complex*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<(ae_int_t)_length; i++)
        {
            jobject elem = (*env)->GetObjectArrayElement(env, jarray, i);
            if( elem==NULL )
            {
                *e_flag = X_INPUT_FAILURE;
                *e_msg  = "ALGLIB: input complex 1D array has null elements";
                return;
            }
            p[i].x = (*env)->GetDoubleField(env, elem, fid_complex_x);
            p[i].y = (*env)->GetDoubleField(env, elem, fid_complex_y);
        }
    }
    else
        CRITICAL_ASSERT(0, "ALGLIB: integrity check 1934 at x_vector_from_array() failed");
}

/**************************************************************************************************
Creates X-vector structure from Java array.

INPUT PARAMETERS:
    env             -   JNI env
    x               -   x-vector structure, depending on x_operation can be considered initialized
                        or uninitialized
    jarray          -   pointer to Java 1D array or corresponding relocatable wrapper object.
                        Can be NULL, in this case x is initialized as empty vector (x_operation MUST be X_CREATE).
    is_rlc_wrapper  -   if true, jarray points to an instance of relocatable wrapper (a class that
                        allows to return reallocated arrays, emulating passing parameters by
                        reference)
    datatype        -   DT_BOOL, DT_INT, DT_REAL or DT_COMPLEX
    x_operation     -   one of the following:
                        * X_CREATE - x points to uninitialized instance, new array is created
                        * X_SET    - x points to initialized array (which may have different datatype),
                                     previois contents is freed prior to allocating new storage
                        * X_REWRITE- x points to initialized array of the same size and type, 
                                     array contents is rewritten without reallocation
    e_flag          -   points to exception flag
    e_msg           -   points to exception message
    
OUTPUT PARAMETERS:
    x               -   new X-array (on exception it is still valid, although only partially
                        initialized, and you should properly clear it in order to avoid memory
                        leaks)
    e_flag          -   on exception it is set to X_INPUT_FAILURE, on success is not modified
    e_msg           -   on exception it is set to error message, on success is not modified
    
EXCEPTIONS AND ERROR HANDLING:
    this function sets e_flag only in the following cases:
    * input is a non-rectangular matrix (rows sizes differ, some rows are null)
    * input is a complex matrix that has null elements
    
    All other errors are considered critical integrity failures, with error message being printed
    and program being terminated immediately.
**************************************************************************************************/
static void x_matrix_from_array(JNIEnv *env, x_matrix *x, jobject jarray, int is_rlc_wrapper, int datatype, int x_operation, int32_t *e_flag, const char **e_msg)
{
    /* determine type signatures and sizes */
    const char *arr_sig = NULL;
    ae_int_t elem_size = 0;
    if( datatype==DT_BOOL )
    {
        arr_sig = "[[Z";
        elem_size = sizeof(ae_bool);
    }
    if( datatype==DT_INT )
    {
        arr_sig = "[[I";
        elem_size = sizeof(ae_int_t);
    }
    if( datatype==DT_REAL )
    {
        arr_sig = "[[D";
        elem_size = sizeof(double);
    }
    if( datatype==DT_COMPLEX )
    {
        arr_sig = "[[Lalglib/alglib$complex;";
        elem_size = sizeof(ae_complex);
    }
    CRITICAL_ASSERT((arr_sig!=NULL) && (elem_size>0), "ALGLIB: integrity check 5839 at x_matrix_from_array() failed");
    
    /* if array is passed via relocatable wrapper, extract it from the wrapper object */
    if( is_rlc_wrapper )
    {
        // TODO: reuse RLC classes and fids !!!!!!!!!!!!!!!!!!!!!!!!!!
        jclass  rlc_class = (*env)->GetObjectClass(env, jarray);
        CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 6439 at x_matrix_from_array() failed");
        //
        jfieldID fid_val = (*env)->GetFieldID(env, rlc_class, "val", arr_sig);
        CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 6740 at x_matrix_from_array() failed");
        //
        jarray = (*env)->GetObjectField(env, jarray, fid_val);
    }
    
    /* handle NULL input */
    if( jarray==NULL )
    {
        CRITICAL_ASSERT(x_operation==X_CREATE, "ALGLIB: integrity check 6855 failed");
        x_matrix_init_empty(x, datatype);
        return;
    }
    
    /* read array rows/cols,  */
    CRITICAL_ASSERT((AE_DATA_ALIGN%elem_size)==0,"ALGLIB: integrity check 8355 failed");
    jsize _rows = jarray!=NULL ? (*env)->GetArrayLength(env, jarray) : (jsize)0;
    jsize _cols = _rows>0 ? (*env)->GetArrayLength(env, (*env)->GetObjectArrayElement(env, jarray, _rows-1)) : (jsize)0;
    jsize _stride = iDivUp(_cols*elem_size,AE_DATA_ALIGN)*AE_DATA_ALIGN/elem_size;
    
    /* initialize x-rows, x-cols and type of X-matrix depending on x_operation */
    if( x_operation==X_CREATE )
    {
        x->datatype = datatype;
        x->rows = _rows;
        x->cols = _cols;
        x->stride = _stride;
        x->on_free = ACT_XFREE;
        if( x_malloc(&x->x_ptr.p_ptr, x->stride*x->rows*elem_size)!=X_OK )
            CRITICAL_ASSERT(0, "ALGLIB: integrity check 8644 at x_matrix_from_array() failed");
        x->last_action = ACT_UNCHANGED;
    }
    if( x_operation==X_SET )
    {
        if( x->on_free==ACT_XFREE )
            x_free(x->x_ptr.p_ptr);
        x->datatype = datatype;
        x->rows = _rows;
        x->cols = _cols;
        x->stride = _stride;
        x->on_free = ACT_XFREE;
        if( x_malloc(&x->x_ptr.p_ptr, x->stride*x->rows*elem_size)!=X_OK )
            CRITICAL_ASSERT(0, "ALGLIB: integrity check 8645 at x_matrix_from_array() failed");
        x->last_action = ACT_NEW_LOCATION;
    }
    if( x_operation==X_REWRITE )
    {
        CRITICAL_ASSERT(x->datatype==datatype,  "ALGLIB: trying to X_REWRITE x-matrix - types don't match");
        CRITICAL_ASSERT(x->rows==_rows,         "ALGLIB: trying to X_REWRITE x-matrix - sizes don't match");
        CRITICAL_ASSERT(x->cols==_cols,         "ALGLIB: trying to X_REWRITE x-matrix - sizes don't match");
        CRITICAL_ASSERT(x->last_action==ACT_UNCHANGED ||
                        x->last_action==ACT_SAME_LOCATION ||
                        x->last_action==ACT_NEW_LOCATION, "ALGLIB: integrity check 7353 failed");
        if( x->last_action==ACT_UNCHANGED )
            x->last_action = ACT_SAME_LOCATION;
    }
   
    /* read array items */
    if( _rows!=0 && _cols!=0 )
    {
        if( datatype==DT_BOOL )
        {
            ae_bool *out_row = (ae_bool*)x->x_ptr.p_ptr;
            for(ae_int_t i=0; i<(ae_int_t)_rows; i++)
            {
                /* get row and perform integrity checks */
                jobject j_row = (*env)->GetObjectArrayElement(env, jarray, i);
                if( j_row==NULL )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has null rows";
                    return;
                }
                if( (*env)->GetArrayLength(env, j_row)!=_cols )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has non-rectangular shape";
                    return;
                }
                
                /* read binary data */
                jboolean *row_array = (*env)->GetBooleanArrayElements(env, j_row, NULL);
                CRITICAL_ASSERT(row_array!=NULL, "ALGLIB: integrity check 0757 at x_matrix_from_array() failed");
                for(ae_int_t j=0; j<(ae_int_t)_cols; j++)
                    out_row[j] = row_array[j]!=0;
                (*env)->ReleaseBooleanArrayElements(env, j_row, row_array, 0);
                out_row += x->stride;
            }
        }
        else if( datatype==DT_INT )
        {
            ae_int_t *out_row = (ae_int_t*)x->x_ptr.p_ptr;
            for(ae_int_t i=0; i<(ae_int_t)_rows; i++)
            {
                /* get row and perform integrity checks */
                jobject j_row = (*env)->GetObjectArrayElement(env, jarray, i);
                if( j_row==NULL )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has null rows";
                    return;
                }
                if( (*env)->GetArrayLength(env, j_row)!=_cols )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has non-rectangular shape";
                    return;
                }
                
                /* read binary data */
                jint *row_array = (*env)->GetIntArrayElements(env, j_row, NULL);
                CRITICAL_ASSERT(row_array!=NULL, "ALGLIB: integrity check 0755 at x_matrix_from_array() failed");
                for(ae_int_t j=0; j<(ae_int_t)_cols; j++)
                    out_row[j] = row_array[j];
                (*env)->ReleaseIntArrayElements(env, j_row, row_array, 0);
                out_row += x->stride;
            }
        }
        else if( datatype==DT_REAL )
        {
            double *out_row = (double*)x->x_ptr.p_ptr;
            for(ae_int_t i=0; i<(ae_int_t)_rows; i++)
            {
                /* get row and perform integrity checks */
                jobject j_row = (*env)->GetObjectArrayElement(env, jarray, i);
                if( j_row==NULL )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has null rows";
                    return;
                }
                if( (*env)->GetArrayLength(env, j_row)!=_cols )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has non-rectangular shape";
                    return;
                }
                
                /* read binary data */
                
                /*double *row_array = (*env)->GetDoubleArrayElements(env, j_row, NULL);
                CRITICAL_ASSERT(row_array!=NULL, "ALGLIB: integrity check 0759 at x_matrix_from_array() failed");
                for(ae_int_t j=0; j<(ae_int_t)_cols; j++)
                    out_row[j] = row_array[j];
                (*env)->ReleaseDoubleArrayElements(env, j_row, row_array, 0);*/
                (*env)->GetDoubleArrayRegion(env, j_row, 0, _cols, (jdouble*)out_row);
                out_row += x->stride;
            }
        }
        else if( datatype==DT_COMPLEX )
        {
            ae_complex *out_row = (ae_complex*)x->x_ptr.p_ptr;
            for(ae_int_t i=0; i<(ae_int_t)_rows; i++)
            {
                /* get row and perform integrity checks */
                jobject j_row = (*env)->GetObjectArrayElement(env, jarray, i);
                if( j_row==NULL )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has null rows";
                    return;
                }
                if( (*env)->GetArrayLength(env, j_row)!=_cols )
                {
                    *e_flag = X_INPUT_FAILURE;
                    *e_msg  = "ALGLIB: input 2D array has non-rectangular shape";
                    return;
                }
                
                /* read complex data */
                for(ae_int_t j=0; j<(ae_int_t)_cols; j++)
                {
                    jobject elem = (*env)->GetObjectArrayElement(env, j_row, j);
                    if( elem==NULL )
                    {
                        *e_flag = X_INPUT_FAILURE;
                        *e_msg  = "ALGLIB: input complex 2D array has null complex elements";
                        return;
                    }
                    out_row[j].x = (*env)->GetDoubleField(env, elem, fid_complex_x);
                    out_row[j].y = (*env)->GetDoubleField(env, elem, fid_complex_y);
                }
                out_row += x->stride;
            }
        }
        else
            CRITICAL_ASSERT(0, "ALGLIB: integrity check 4758 at x_matrix_from_array() failed");
    }
}

/*
 * Converts x-vector to Java array, handling various cases:
 * 1. is_rlc_wrapper==false, j_array_or_wrapper==NULL:
 *        allocates new jarray, fills it and returns reference to it
 * 2. is_rlc_wrapper==false, j_array_or_wrapper!=NULL:
 *        copies data to jarray, returns copy of j_array_or_wrapper.
 *        sizes of x-vector and jarray MUST match, program will be aborted otherwise
 * 3. is_rlc_wrapper==true:
 *        copies data to the array stored in the relocatable wrapper,
 *        reallocating it and saving reallocated array to the wrapper if needed.
 *        Returns copy of jarray (not wrapper!).
 *
 */
static jobject x_vector_to_array(JNIEnv *env, x_vector *x, jobject j_array_or_wrapper, int is_rlc_wrapper)
{
    int is_relocated = ae_false;
    int rlc_allowed  = is_rlc_wrapper || (j_array_or_wrapper==NULL);
    //TODO: check that x->cnt fits into Java limits!!!!!!!!!!!!!!!!!!!
    
    /* determine type signatures */
    const char *arr_sig = NULL;
    if( x->datatype==DT_BOOL )
        arr_sig = "[Z";
    if( x->datatype==DT_INT )
        arr_sig = "[I";
    if( x->datatype==DT_REAL )
        arr_sig = "[D";
    if( x->datatype==DT_COMPLEX )
        arr_sig = "[Lalglib/alglib$complex;";
    CRITICAL_ASSERT(arr_sig!=NULL, "ALGLIB: integrity check 2009 at x_vector_to_array() failed");
    
    /* get array and relocatable wrapper (if present) pointers */
    jobject j_arr=NULL, j_wrp=NULL;
    jclass  rlc_class=NULL;
    jfieldID fid_val=NULL;
    if( is_rlc_wrapper )
    {
        CRITICAL_ASSERT(j_array_or_wrapper!=NULL, "ALGLIB: integrity check 2456 at x_vector_to_array() failed");
        //
        rlc_class = (*env)->GetObjectClass(env, j_array_or_wrapper);
        CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 2712 at x_vector_to_array() failed");
        //
        fid_val = (*env)->GetFieldID(env, rlc_class, "val", arr_sig);
        CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 3013 at x_vector_to_array() failed");
        //
        j_arr = (*env)->GetObjectField(env, j_array_or_wrapper, fid_val);
        j_wrp = j_array_or_wrapper;
    }
    else
        j_arr = j_array_or_wrapper;
    
    /*
     * determine current length of the array.
     * it is set to -1 if we have relocatable array wrapper with val==null;
     * the idea is that -1 will force us to allocate output array even if we have zero-length result.
     */
    ae_int_t cur_jlen = (*env)->IsSameObject(env,j_arr,NULL) ? -1 : (*env)->GetArrayLength(env,j_arr);
    
    /* allocate array to store the output or reuse already existing j_arr (we compare lengths - if they match, we reuse, otherwise we reallocate) */
    jobject j_out = j_arr;
    if( x->cnt!=cur_jlen )
    {
        CRITICAL_ASSERT(rlc_allowed, "ALGLIB: integrity check 4956 at x_vector_to_array() failed");
        if( x->datatype==DT_BOOL )
            j_out = (*env)->NewBooleanArray(env, aeint2jsize(x->cnt));
        else if( x->datatype==DT_INT )
            j_out = (*env)->NewIntArray(env, aeint2jsize(x->cnt));
        else if( x->datatype==DT_REAL )
            j_out = (*env)->NewDoubleArray(env, aeint2jsize(x->cnt));
        else if( x->datatype==DT_COMPLEX )
            j_out = (*env)->NewObjectArray(env, aeint2jsize(x->cnt), class_complex, NULL);
        else
            CRITICAL_ASSERT(0, "ALGLIB: integrity check 5332 at x_vector_to_array() failed");
        CRITICAL_ASSERT(j_out!=NULL, "ALGLIB: integrity check 5333 at x_vector_to_array() failed");
        is_relocated = ae_true;
    }
    
    /* output elements to the array */
    if( x->datatype==DT_BOOL )
    {
        jboolean *out_array = (*env)->GetBooleanArrayElements(env, j_out, NULL);
        CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 9654 at x_vector_init_from() failed");
        ae_bool *p = (ae_bool*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<x->cnt; i++)
            out_array[i] = p[i] ? JNI_TRUE : JNI_FALSE;
        (*env)->ReleaseBooleanArrayElements(env, j_out, out_array, 0);
    }
    else if( x->datatype==DT_INT )
    {
        jint *out_array = (*env)->GetIntArrayElements(env, j_out, NULL);
        CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 9655 at x_vector_init_from() failed");
        ae_int_t *p = (ae_int_t*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<x->cnt; i++)
            out_array[i] = p[i]; // TODO: 32/64!!!!!!!!!!!!!!1111
        (*env)->ReleaseIntArrayElements(env, j_out, out_array, 0);
    }
    else if( x->datatype==DT_REAL )
    {
        double *out_array = (*env)->GetDoubleArrayElements(env, j_out, NULL);
        CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 9656 at x_vector_init_from() failed");
        double *p = (double*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<x->cnt; i++)
            out_array[i] = p[i];
        (*env)->ReleaseDoubleArrayElements(env, j_out, out_array, 0);
    }
    else if( x->datatype==DT_COMPLEX )
    {
        ae_complex *p = (ae_complex*)x->x_ptr.p_ptr;
        for(ae_int_t i=0; i<x->cnt; i++)
            (*env)->SetObjectArrayElement(env, j_out, i, (*env)->NewObject(env, class_complex, mid_complex_init2, p[i].x, p[i].y));
    }
    else
        CRITICAL_ASSERT(0, "ALGLIB: integrity check 6539 at x_vector_to_array() failed");
    
    /* if relocation was performed, update relocatable array wrapper */
    if( is_relocated && is_rlc_wrapper )
    {
        CRITICAL_ASSERT((rlc_class!=NULL) && (fid_val!=NULL), "ALGLIB: integrity check 7641 at x_vector_to_array() failed");
        (*env)->SetObjectField(env, j_wrp, fid_val, j_out);
    }
    
    /* done */
    return j_out;
}

/*
 * Converts x-matrix to Java array of arrays, handling various cases:
 * 1. is_rlc_wrapper==false, j_array_or_wrapper==NULL:
 *        allocates new jarray, fills it and returns reference to it
 * 2. is_rlc_wrapper==false, j_array_or_wrapper!=NULL:
 *        copies data to jarray, returns copy of j_array_or_wrapper.
 *        sizes of x-matrix and jarray MUST match, program will be aborted otherwise
 * 3. is_rlc_wrapper==true:
 *        copies data to the array stored in the relocatable wrapper,
 *        reallocating it and saving reallocated array to the wrapper if needed.
 *        Returns copy of jarray (not wrapper!).
 *
 */
static jobject x_matrix_to_array(JNIEnv *env, x_matrix *x, jobject j_array_or_wrapper, int is_rlc_wrapper)
{
    int is_relocated = ae_false;
    int rlc_allowed  = is_rlc_wrapper || (j_array_or_wrapper==NULL);
    
    /* critical integrity check */
    CRITICAL_ASSERT((x->rows==0 && x->cols==0) || (x->rows>0 && x->cols>0), "ALGLIB: integrity check 2556 at x_matrix_to_array() failed");
    //TODO: check that x->cnt fits into Java limits!!!!!!!!!!!!!!!!!!!

    /* obtain array signature and element class */
    const char *arr_sig = NULL;
    jclass  elem_class=NULL;
    if( x->datatype==DT_BOOL )
    {
        arr_sig = "[[Z";
        elem_class = class_bool1d;
    }
    if( x->datatype==DT_INT )
    {
        arr_sig = "[[I";
        elem_class = class_int1d;
    }
    if( x->datatype==DT_REAL )
    {
        arr_sig = "[[D";
        elem_class = class_double1d;
    }
    if( x->datatype==DT_COMPLEX )
    {
        arr_sig = "[[Lalglib/alglib$complex;";
        elem_class = class_complex1d;
    }
    CRITICAL_ASSERT(arr_sig!=NULL, "ALGLIB: integrity check 1405 at x_matrix_to_array() failed");
    
    /* get array and relocatable wrapper (if present) pointers */
    jobject j_mat=NULL, j_wrp=NULL;
    jclass  rlc_class=NULL;
    jfieldID fid_val=NULL;
    if( is_rlc_wrapper )
    {
        CRITICAL_ASSERT(j_array_or_wrapper!=NULL, "ALGLIB: integrity check 2206 at x_matrix_to_array() failed");
        //
        rlc_class = (*env)->GetObjectClass(env, j_array_or_wrapper);
        CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 2506 at x_matrix_to_array() failed");
        //
        fid_val = (*env)->GetFieldID(env, rlc_class, "val", arr_sig);
        CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 2806 at x_matrix_to_array() failed");
        //
        j_mat = (*env)->GetObjectField(env, j_array_or_wrapper, fid_val);
        j_wrp = j_array_or_wrapper;
    }
    else
        j_mat = j_array_or_wrapper;
    
    /*
     * determine current size of the matrix.
     * rows/cols is set to -1 if we have relocatable array wrapper with val==null;
     * the idea is that -1 will force us to allocate output array even if we have zero-length result.
     */
    ae_int_t cur_jrows, cur_jcols;
    cur_jrows = (*env)->IsSameObject(env,j_mat,NULL) ? -1 : (*env)->GetArrayLength(env,j_mat);
    if( cur_jrows>=1 )
        cur_jcols = (*env)->GetArrayLength(env, (*env)->GetObjectArrayElement(env,j_mat,cur_jrows-1));
    else if( cur_jrows==0 )
        cur_jcols = 0;
    else
        cur_jcols = -1;

    /* allocate array to store the output or reuse already existing j_mat (we compare lengths - if they match, we reuse, otherwise we reallocate) */
    jobject j_res = j_mat;
    if( x->rows!=cur_jrows || x->cols!=cur_jcols )
    {
        CRITICAL_ASSERT(rlc_allowed, "ALGLIB: integrity check 5314 at x_matrix_to_array() failed");
        j_res = (*env)->NewObjectArray(env, aeint2jsize(x->rows), elem_class, NULL);
        CRITICAL_ASSERT(j_res!=NULL, "ALGLIB: integrity check 9637 at x_matrix_to_array() failed");
        for(ae_int_t i=0; i<x->rows; i++)
        {
            jobject inner = NULL;
            if( x->datatype==DT_BOOL )
                inner = (*env)->NewBooleanArray(env, aeint2jsize(x->cols));
            else if( x->datatype==DT_INT )
                inner = (*env)->NewIntArray(env, aeint2jsize(x->cols));
            else if( x->datatype==DT_REAL )
                inner = (*env)->NewDoubleArray(env, aeint2jsize(x->cols));
            else if( x->datatype==DT_COMPLEX )
                inner = (*env)->NewObjectArray(env, aeint2jsize(x->cols), class_complex, NULL);
            CRITICAL_ASSERT(inner!=NULL, "ALGLIB: integrity check 5332 at x_matrix_to_array() failed");
            (*env)->SetObjectArrayElement(env, j_res, i, inner);
        }
        is_relocated = ae_true;
    }

    /* output elements to the array */
    void *p_out = x->x_ptr.p_ptr;
    for(ae_int_t row_idx=0; row_idx<x->rows; row_idx++)
    {
        jobject j_row = (*env)->GetObjectArrayElement(env, j_res, row_idx);
        if( x->datatype==DT_BOOL )
        {
            jboolean *out_array = (*env)->GetBooleanArrayElements(env, j_row, NULL);
            CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 2398 at x_matrix_to_array() failed");
            ae_bool *p = (ae_bool*)p_out;
            for(ae_int_t i=0; i<x->cols; i++)
                out_array[i] = p[i] ? JNI_TRUE : JNI_FALSE;
            (*env)->ReleaseBooleanArrayElements(env, j_row, out_array, 0);
            p_out = p+x->stride;
        }
        else if( x->datatype==DT_INT )
        {
            jint *out_array = (*env)->GetIntArrayElements(env, j_row, NULL);
            CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 2399 at x_matrix_to_array() failed");
            ae_int_t *p = (ae_int_t*)p_out;
            for(ae_int_t i=0; i<x->cols; i++)
                out_array[i] = p[i]; // TODO: 32/64!!!!!!!!!!!!!!1111
            (*env)->ReleaseIntArrayElements(env, j_row, out_array, 0);
            p_out = p+x->stride;
        }
        else if( x->datatype==DT_REAL )
        {
            double *out_array = (*env)->GetDoubleArrayElements(env, j_row, NULL);
            CRITICAL_ASSERT(out_array!=NULL, "ALGLIB: integrity check 2400 at x_matrix_to_array() failed");
            double *p = (double*)p_out;
            for(ae_int_t i=0; i<x->cols; i++)
                out_array[i] = p[i];
            (*env)->ReleaseDoubleArrayElements(env, j_row, out_array, 0);
            p_out = p+x->stride;
        }
        else if( x->datatype==DT_COMPLEX )
        {
            ae_complex *p = (ae_complex*)p_out;
            for(ae_int_t i=0; i<x->cols; i++)
                (*env)->SetObjectArrayElement(env, j_row, i, (*env)->NewObject(env, class_complex, mid_complex_init2, p[i].x, p[i].y));
            p_out = p+x->stride;
        }
        else
            CRITICAL_ASSERT(0, "ALGLIB: integrity check 2401 at x_matrix_to_array() failed");
    }
    
    /* if relocation was performed, update relocatable array wrapper */
    if( is_relocated && is_rlc_wrapper )
    {
        CRITICAL_ASSERT((rlc_class!=NULL) && (fid_val!=NULL), "ALGLIB: integrity check 6110 at x_matrix_to_array() failed");
        (*env)->SetObjectField(env, j_wrp, fid_val, j_res);
    }
    
    /* done */
    return j_res;
}

/*
 *  For a field of an object which is an array of one of X-types (DT_BOOL/DT_INT/DT_REAL/DT_COMPLEX)
 *  performs the following operation:
 *  1) compares its length with min_len
 *  2) if equal or greater, returns original value of the field as jobject
 *  3) otherwise, allocates new array of min_len size and returns new array as jobject. 
 *     Original contents of the array is not preserved.
 *
 *  NOTE: present version supports only DT_REAL
 *
 *  NOTE: min_len<=0 means that the original field value is returned, no matter
 *        what is stored here (an instance or NULL)
 */
static jobject jarray_field_set_length_at_least(JNIEnv *env, jobject obj, jfieldID fid, int datatype, ae_int_t min_len)
{   
    jobject ori_array = (*env)->GetObjectField(env, obj, fid);
    if( min_len<=0 )
        return ori_array;
    ae_int_t ori_len = (*env)->IsSameObject(env,ori_array,NULL) ? 0 : (*env)->GetArrayLength(env,ori_array);
    if( ori_len>=min_len )
        return ori_array;
    CRITICAL_ASSERT(datatype==DT_REAL, "ALGLIB: integrity check 4819 at jarray_field_set_length_at_least() failed");
    jobject new_array = (*env)->NewDoubleArray(env, aeint2jsize(min_len));
    (*env)->SetObjectField(env, obj, fid, new_array);
    return new_array;
}

static void x_vector_clear(x_vector *x)
{
    if( x->on_free==ACT_XFREE )
        x_free(x->x_ptr.p_ptr);
    x->cnt = 0;
    x->x_ptr.p_ptr = NULL;
}

static void x_matrix_clear(x_matrix *x)
{
    if( x->on_free==ACT_XFREE )
        x_free(x->x_ptr.p_ptr);
    x->rows = 0;
    x->cols = 0;
    x->stride = 0;
    x->x_ptr.p_ptr = NULL;
}
           
static void xbool_to_mutbool(JNIEnv *env, ae_bool val, jobject mutable_bool)
{
    (*env)->SetBooleanField(env, mutable_bool, fid_mutbool_val, val ? JNI_TRUE : JNI_FALSE);
}

static void xint_to_mutint(JNIEnv *env, ae_int_t val, jobject mutable_int)
{
   (*env)->SetIntField(env, mutable_int, fid_mutint_val, aeint2jint(val));
}

static ae_int_t mutint_to_xint(JNIEnv *env, jobject mutable_int)
{
   return (*env)->GetIntField(env, mutable_int, fid_mutint_val);
}

static void xdouble_to_mutdouble(JNIEnv *env, double val, jobject mutable_double)
{
   (*env)->SetDoubleField(env, mutable_double, fid_mutdouble_val, val);
}
           
static double mutdouble_to_xdouble(JNIEnv *env, jobject mutable_double)
{
   return (*env)->GetDoubleField(env, mutable_double, fid_mutdouble_val);
}

static ae_complex jcomplex_to_xcomplex(JNIEnv *env, jobject jval)
{
  ae_complex r;
  r.x = (*env)->GetDoubleField(env, jval, fid_complex_x);
  r.y = (*env)->GetDoubleField(env, jval, fid_complex_y);
  return r;
}
           
static void xcomplex_to_mutcomplex(JNIEnv *env, ae_complex val, jobject mutable_complex)
{
   (*env)->SetObjectField(env, mutable_complex, fid_mutcomplex_val, (*env)->NewObject(env, class_complex, mid_complex_init2, val.x, val.y));
}

static void xobject_to_mutlong(JNIEnv *env, object_ptr_t obj_ptr, jobject mutable_long)
{
   (*env)->SetLongField(env, mutable_long, fid_mutlong_val, ptr2long(obj_ptr));
}
           
static void xstring_to_mutstring_ignorenull(JNIEnv *env, const char *s, jobject mutable_string)
{
    if( s==NULL )
        return;
   (*env)->SetObjectField(env, mutable_string, fid_mutstring_val, (*env)->NewStringUTF(env,s));
}

