    // This function initializes X-structure (its previous content is ignored)
    static void x_xdebugrecord1_init(x_xdebugrecord1 *x)
    {
        x->i = 0;
        x->c.x = 0;
        x->c.y = 0;
        x_vector_init_empty(&x->a, DT_REAL);
    }

// This function finalizes fields of X-structure (however, memory occupied by structure itself is not freed)
// After destruction structure becomes unusable and should be re-initialized if you want to use it
static void x_xdebugrecord1_clear(x_xdebugrecord1 *x)
{
    x_vector_clear(&x->a);
}

//
// This function initializes X-structure by appropriate Java instance
// (previous contents of X structure is ignored)
// 
// If jrecord_or_wrapper is NULL (is_rlc_wrapper MUST be false), the structure is initialized by zeros.
// If any of the Java structure fields is null, corresponding field of the X-structure is initialized by zeros.
//    e_flag          -   on exception it is set to X_ASSERTION_FAILED, on success is not modified
//    e_msg           -   on exception it is set to error message, on success is not modified
//    
//EXCEPTIONS AND ERROR HANDLING:
//    this function sets e_flag only in the following cases:
//    * input is a non-rectangular matrix (rows sizes differ, some rows are null)
//    * input is a complex matrix that has null elements
//    
//    All other errors are considered critical integrity failures, with error message being printed
//    and program being terminated immediately.
//
static void x_xdebugrecord1_init_from(JNIEnv *env, x_xdebugrecord1 *x, jobject jrecord_or_wrapper, ae_bool is_rlc_wrapper, int32_t *e_flag, const char **e_msg)
{
/* extract record from the relocatable wrapper (if present) */
jobject  j_rec=NULL;
jclass   j_cls=NULL;
if( is_rlc_wrapper )
{
jclass   rlc_class=NULL;
jfieldID fid_val=NULL;
//
rlc_class = (*env)->GetObjectClass(env, jrecord_or_wrapper);
CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 7343 at x_xdebugrecord1_init_from() failed");
//
fid_val = (*env)->GetFieldID(env, rlc_class, "val", "Ljava/lang/Object;");
CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 7644 at x_xdebugrecord1_init_from() failed");
//
j_rec = (*env)->GetObjectField(env, jrecord_or_wrapper, fid_val);
}
else
j_rec = jrecord_or_wrapper;

/* handle NULL input */
if( j_rec==NULL )
{
x_xdebugrecord1_init(x);
return;
}

/* determine class */
j_cls = (*env)->GetObjectClass(env, j_rec);
CRITICAL_ASSERT(j_cls!=NULL, "ALGLIB: integrity check 8552 at x_xdebugrecord1_init_from() failed");
    x->i = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"i", "I", "ALGLIB: loading 'i' at x_xdebugrecord1_init_from() failed"));
    jobject _c_c = (*env)->GetObjectField(env, j_rec, AssertGetFieldID(env,j_cls,"c", "Lalglib/alglib$complex;", "ALGLIB: loading 'c' at x_xdebugrecord1_init_from() failed"));
    x->c.x = (*env)->GetDoubleField(env, _c_c, fid_complex_x);
    x->c.y = (*env)->GetDoubleField(env, _c_c, fid_complex_y);
    x_vector_from_array(env, &x->a, (*env)->GetObjectField(env, j_rec, AssertGetFieldID(env,j_cls,"a", "[D", "ALGLIB: loading 'a' at x_xdebugrecord1_init_from() failed")), ae_false, DT_REAL, X_CREATE, e_flag, e_msg);
}

//
// This function initializes Java object from X instance
// Target object can be optionally wrapped into relocatable wrapper, as indicated by is_rlc_wrapper parameter
// In the latter case, wrapper.val can be null - the object will be automatically created.
//
// Similarly to x_vector_to_array(), several cases are supported:
// 1. is_rlc_wrapper==false, j_record_or_wrapper==NULL:
//        allocates new record, fills it and returns reference to it
// 2. is_rlc_wrapper==false, j_record_or_wrapper!=NULL:
//        copies data to record, returns copy of j_record_or_wrapper.
// 3. is_rlc_wrapper==true:
//        copies data to the record stored in the relocatable wrapper,
//        allocating it and saving newly allocated record to the wrapper if needed (wrapper.val==null).
//        Returns copy of the record (not wrapper!).
//
static jobject x_xdebugrecord1_to_record(JNIEnv *env, x_xdebugrecord1 *x, jobject jrecord_or_wrapper, ae_bool is_rlc_wrapper)
{
/* get record/object and relocatable wrapper (if present) pointers */
jobject  j_rec=NULL, j_wrp=NULL;
jclass   rlc_class=NULL;
jfieldID fid_val=NULL;
if( is_rlc_wrapper )
{
rlc_class = (*env)->GetObjectClass(env, jrecord_or_wrapper);
CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 1623 at x_xdebugrecord1_to_record() failed");
//
fid_val = (*env)->GetFieldID(env, rlc_class, "val", "Ljava/lang/Object;");
CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 1924 at x_xdebugrecord1_to_record() failed");
//
j_rec = (*env)->GetObjectField(env, jrecord_or_wrapper, fid_val);
j_wrp = jrecord_or_wrapper;
}
else
j_rec = jrecord_or_wrapper;

/* if record is null, create record instance; later it will be saved into the relocatable wrapper */
ae_bool was_relocated = ae_false;
jclass rec_cls = (*env)->FindClass(env, "alglib/alglib$xdebugrecord1");
CRITICAL_ASSERT(rec_cls!=NULL, "ALGLIB: integrity check 3429 at x_xdebugrecord1_to_record() failed");
if( j_rec==NULL )
{
jmethodID midInit = (*env)->GetMethodID(env, rec_cls, "<init>", "()V");
CRITICAL_ASSERT(midInit!=NULL, "ALGLIB: integrity check 3630 at x_xdebugrecord1_to_record() failed");
j_rec = (*env)->NewObject(env, rec_cls, midInit);
CRITICAL_ASSERT(j_rec!=NULL, "ALGLIB: integrity check 3935 at x_xdebugrecord1_to_record() failed");
was_relocated = ae_true;
}
    (*env)->SetIntField(env, j_rec, AssertGetFieldID(env, rec_cls, "i", "I", "ALGLIB: error unpacking j_rec.i at x_xdebugrecord1_to_record()"), aeint2jint(x->i));
    (*env)->SetObjectField(env, j_rec, AssertGetFieldID(env, rec_cls, "c", "Lalglib/alglib$complex;", "ALGLIB: error unpacking j_rec.c at x_xdebugrecord1_to_record()"), (*env)->NewObject(env, class_complex, mid_complex_init2, x->c.x, x->c.y));
    (*env)->SetObjectField(env, j_rec, AssertGetFieldID(env, rec_cls, "a", "[D", "ALGLIB: error unpacking j_rec.a at x_xdebugrecord1_to_record()"), x_vector_to_array(env, &x->a, (jobject)NULL, ae_false));
/* if object was relocated AND relocatable wrapper was passed, update wrapper.val */
if( was_relocated && is_rlc_wrapper )
(*env)->SetObjectField(env, j_wrp, fid_val, j_rec);

/* done */
return j_rec;
}

