    (*env)->SetDoubleField(env, j_rec, AssertGetFieldID(env, rec_cls, "f", "D", "ALGLIB: error unpacking j_rec.f at x_minlpreport_to_record()"), x->f);
    (*env)->SetObjectField(env, j_rec, AssertGetFieldID(env, rec_cls, "lagbc", "[D", "ALGLIB: error unpacking j_rec.lagbc at x_minlpreport_to_record()"), x_vector_to_array(env, &x->lagbc, (jobject)NULL, ae_false));
