    (*env)->SetObjectField(env, j_rec, AssertGetFieldID(env, rec_cls, "stats", "[I", "ALGLIB: error unpacking j_rec.stats at x_minlpreport_to_record()"), x_vector_to_array(env, &x->stats, (jobject)NULL, ae_false));
    (*env)->SetDoubleField(env, j_rec, AssertGetFieldID(env, rec_cls, "primalerror", "D", "ALGLIB: error unpacking j_rec.primalerror at x_minlpreport_to_record()"), x->primalerror);
    (*env)->SetDoubleField(env, j_rec, AssertGetFieldID(env, rec_cls, "dualerror", "D", "ALGLIB: error unpacking j_rec.dualerror at x_minlpreport_to_record()"), x->dualerror);
