    x->nmv = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"nmv", "I", "ALGLIB: loading 'nmv' at x_minqpreport_init_from() failed"));
    x->ncholesky = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"ncholesky", "I", "ALGLIB: loading 'ncholesky' at x_minqpreport_init_from() failed"));
    x->terminationtype = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"terminationtype", "I", "ALGLIB: loading 'terminationtype' at x_minqpreport_init_from() failed"));
