    x->cerr = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"cerr", "D", "ALGLIB: loading 'cerr' at x_minnsreport_init_from() failed"));
    x->lcerr = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"lcerr", "D", "ALGLIB: loading 'lcerr' at x_minnsreport_init_from() failed"));
    x->nlcerr = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"nlcerr", "D", "ALGLIB: loading 'nlcerr' at x_minnsreport_init_from() failed"));
