    (*env)->SetIntField(env, j_rec, AssertGetFieldID(env, rec_cls, "iterationscount", "I", "ALGLIB: error unpacking j_rec.iterationscount at x_minnsreport_to_record()"), aeint2jint(x->iterationscount));
