jobject  j_rec=NULL;
jclass   j_cls=NULL;
if( is_rlc_wrapper )
{
jclass   rlc_class=NULL;
jfieldID fid_val=NULL;
//
rlc_class = (*env)->GetObjectClass(env, jrecord_or_wrapper);
CRITICAL_ASSERT(rlc_class!=NULL, "ALGLIB: integrity check 7343 at x_autogkreport_init_from() failed");
//
fid_val = (*env)->GetFieldID(env, rlc_class, "val", "Ljava/lang/Object;");
CRITICAL_ASSERT(fid_val!=NULL, "ALGLIB: integrity check 7644 at x_autogkreport_init_from() failed");
//
j_rec = (*env)->GetObjectField(env, jrecord_or_wrapper, fid_val);
}
else
j_rec = jrecord_or_wrapper;

/* handle NULL input */
if( j_rec==NULL )
{
x_autogkreport_init(x);
return;
}

/* determine class */
j_cls = (*env)->GetObjectClass(env, j_rec);
CRITICAL_ASSERT(j_cls!=NULL, "ALGLIB: integrity check 8552 at x_autogkreport_init_from() failed");
    x->terminationtype = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"terminationtype", "I", "ALGLIB: loading 'terminationtype' at x_autogkreport_init_from() failed"));
    x->nfev = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"nfev", "I", "ALGLIB: loading 'nfev' at x_autogkreport_init_from() failed"));
    x->nintervals = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"nintervals", "I", "ALGLIB: loading 'nintervals' at x_autogkreport_init_from() failed"));
