else
j_rec = jrecord_or_wrapper;

/* handle NULL input */
if( j_rec==NULL )
{
x_rbfreport_init(x);
return;
}

/* determine class */
j_cls = (*env)->GetObjectClass(env, j_rec);
CRITICAL_ASSERT(j_cls!=NULL, "ALGLIB: integrity check 8552 at x_rbfreport_init_from() failed");
