    x->maxerror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"maxerror", "D", "ALGLIB: loading 'maxerror' at x_rbfreport_init_from() failed"));
    x->arows = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"arows", "I", "ALGLIB: loading 'arows' at x_rbfreport_init_from() failed"));
    x->acols = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"acols", "I", "ALGLIB: loading 'acols' at x_rbfreport_init_from() failed"));
    x->annz = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"annz", "I", "ALGLIB: loading 'annz' at x_rbfreport_init_from() failed"));
    x->iterationscount = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"iterationscount", "I", "ALGLIB: loading 'iterationscount' at x_rbfreport_init_from() failed"));
    x->nmv = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"nmv", "I", "ALGLIB: loading 'nmv' at x_rbfreport_init_from() failed"));
    x->terminationtype = (*env)->GetIntField(env, j_rec, AssertGetFieldID(env,j_cls,"terminationtype", "I", "ALGLIB: loading 'terminationtype' at x_rbfreport_init_from() failed"));
