    (*env)->SetDoubleField(env, j_rec, AssertGetFieldID(env, rec_cls, "energy", "D", "ALGLIB: error unpacking j_rec.energy at x_kmeansreport_to_record()"), x->energy);
    (*env)->SetIntField(env, j_rec, AssertGetFieldID(env, rec_cls, "k", "I", "ALGLIB: error unpacking j_rec.k at x_kmeansreport_to_record()"), aeint2jint(x->k));
