else
j_rec = jrecord_or_wrapper;

/* handle NULL input */
if( j_rec==NULL )
{
x_dfreport_init(x);
return;
}

/* determine class */
j_cls = (*env)->GetObjectClass(env, j_rec);
CRITICAL_ASSERT(j_cls!=NULL, "ALGLIB: integrity check 8552 at x_dfreport_init_from() failed");
    x->relclserror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"relclserror", "D", "ALGLIB: loading 'relclserror' at x_dfreport_init_from() failed"));
    x->avgce = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"avgce", "D", "ALGLIB: loading 'avgce' at x_dfreport_init_from() failed"));
    x->rmserror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"rmserror", "D", "ALGLIB: loading 'rmserror' at x_dfreport_init_from() failed"));
    x->avgerror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"avgerror", "D", "ALGLIB: loading 'avgerror' at x_dfreport_init_from() failed"));
    x->avgrelerror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"avgrelerror", "D", "ALGLIB: loading 'avgrelerror' at x_dfreport_init_from() failed"));
    x->oobrelclserror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"oobrelclserror", "D", "ALGLIB: loading 'oobrelclserror' at x_dfreport_init_from() failed"));
