    x->oobrmserror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"oobrmserror", "D", "ALGLIB: loading 'oobrmserror' at x_dfreport_init_from() failed"));
    x->oobavgerror = (*env)->GetDoubleField(env, j_rec, AssertGetFieldID(env,j_cls,"oobavgerror", "D", "ALGLIB: loading 'oobavgerror' at x_dfreport_init_from() failed"));
