/* if record is null, create record instance; later it will be saved into the relocatable wrapper */
ae_bool was_relocated = ae_false;
jclass rec_cls = (*env)->FindClass(env, "alglib/alglib$mcpdreport");
CRITICAL_ASSERT(rec_cls!=NULL, "ALGLIB: integrity check 3429 at x_mcpdreport_to_record() failed");
